// Turns an incoming enquiry into a booking request. Job types match the values
// produced by the AI enquiry triage template, so the two chain together.

// ---------- EDIT THIS BLOCK ----------
const DURATIONS_MIN = {
  emergency_repair: 120,
  repair: 90,
  quote_request: 45,
  maintenance: 60,
  installation: 240,
};
const DEFAULT_DURATION_MIN = 60;
const HORIZON_DAYS = 14;
// -------------------------------------

return $input.all().map((item) => {
  const body = item.json.body || item.json || {};

  const job_type = String(body.job_type || '').trim().toLowerCase();
  const duration_min = DURATIONS_MIN[job_type] || DEFAULT_DURATION_MIN;

  const booking_id =
    String(body.booking_id || body.job_id || '').trim() ||
    `B-${Date.now().toString(36).toUpperCase()}`;

  const now = new Date();
  const horizon = new Date(now.getTime() + HORIZON_DAYS * 24 * 60 * 60 * 1000);

  return {
    json: {
      booking_id,
      created_at: now.toISOString(),
      customer_name: String(body.customer_name || body.name || '').trim(),
      email: String(body.email || '').trim(),
      phone: String(body.phone || '').trim(),
      job_summary: String(body.job_summary || body.message || 'the work').trim(),
      job_type: job_type || 'unspecified',
      duration_min,
      // Passed to the calendar node so the busy window matches the horizon.
      window_start: now.toISOString(),
      window_end: horizon.toISOString(),
    },
  };
});

// Finds one free slot per day, on up to three different days. Deterministic on
// purpose: a calendar is arithmetic, not a judgement call.

// ---------- EDIT THIS BLOCK ----------
const CONFIG = {
  TIMEZONE: 'America/Chicago',
  OPEN_HOUR: 8,             // 24h clock, business local time
  CLOSE_HOUR: 17,
  WORKDAYS: [1, 2, 3, 4, 5], // 0 = Sunday
  SLOT_STEP_MIN: 30,         // granularity of start times
  BUFFER_MIN: 30,            // travel time kept clear either side of a job
  MIN_NOTICE_HOURS: 4,       // never offer something in the next few hours
  HORIZON_DAYS: 14,
  SLOTS_TO_OFFER: 3,
  // Each offered day aims at a different part of the day, so three options
  // are a real choice rather than the same morning slot three times over.
  PREFERRED_WINDOWS: [[8, 12], [12, 15], [15, 17]],
};
// -------------------------------------

const WEEKDAYS = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };

// Wall-clock parts of an instant in the business timezone.
function localParts(date) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: CONFIG.TIMEZONE, hour12: false,
    weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(date).reduce((acc, p) => ((acc[p.type] = p.value), acc), {});

  return {
    year: Number(parts.year),
    month: Number(parts.month),
    day: Number(parts.day),
    weekday: WEEKDAYS[parts.weekday],
  };
}

// Minutes the business timezone is ahead of UTC at a given instant.
function offsetMinutes(date) {
  const p = new Intl.DateTimeFormat('en-US', {
    timeZone: CONFIG.TIMEZONE, hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
  }).formatToParts(date).reduce((acc, x) => ((acc[x.type] = x.value), acc), {});

  const asUtc = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour % 24, +p.minute, +p.second);
  return (asUtc - date.getTime()) / 60000;
}

// Local wall-clock time to a real instant, correct across daylight saving.
function localToInstant(year, month, day, hour, minute) {
  const naive = Date.UTC(year, month - 1, day, hour, minute);
  let guess = naive;
  for (let pass = 0; pass < 2; pass++) {
    guess = naive - offsetMinutes(new Date(guess)) * 60000;
  }
  return guess;
}

function humanLabel(ms) {
  return new Intl.DateTimeFormat('en-US', {
    timeZone: CONFIG.TIMEZONE,
    weekday: 'long', month: 'long', day: 'numeric',
    hour: 'numeric', minute: '2-digit',
  }).format(new Date(ms));
}

const request = $('Build Booking Request').first().json;
const durationMs = Number(request.duration_min || 60) * 60000;

// Existing appointments, padded with travel buffer on both sides.
const busy = [];
for (const item of $input.all()) {
  const start = item.json?.start?.dateTime || item.json?.start?.date;
  const end = item.json?.end?.dateTime || item.json?.end?.date;
  if (!start || !end) continue;
  busy.push([
    new Date(start).getTime() - CONFIG.BUFFER_MIN * 60000,
    new Date(end).getTime() + CONFIG.BUFFER_MIN * 60000,
  ]);
}

const now = Date.now();
const earliest = now + CONFIG.MIN_NOTICE_HOURS * 60 * 60 * 1000;
const slots = [];

for (let dayOffset = 0; dayOffset < CONFIG.HORIZON_DAYS; dayOffset++) {
  if (slots.length >= CONFIG.SLOTS_TO_OFFER) break;

  const day = localParts(new Date(now + dayOffset * 24 * 60 * 60 * 1000));
  if (!CONFIG.WORKDAYS.includes(day.weekday)) continue;

  const duration = Number(request.duration_min || 60);
  const lastStart = CONFIG.CLOSE_HOUR * 60 - duration;

  // Try this day's preferred part of the day first, then fall back to the rest.
  const preferred = CONFIG.PREFERRED_WINDOWS[slots.length % CONFIG.PREFERRED_WINDOWS.length];
  const windows = [preferred, ...CONFIG.PREFERRED_WINDOWS.filter((w) => w !== preferred)];

  let found = null;

  for (const [fromHour, toHour] of windows) {
    if (found) break;

    const from = Math.max(fromHour * 60, CONFIG.OPEN_HOUR * 60);
    const to = Math.min(toHour * 60 - duration, lastStart);

    for (let minute = from; minute <= to; minute += CONFIG.SLOT_STEP_MIN) {
      const startMs = localToInstant(day.year, day.month, day.day, Math.floor(minute / 60), minute % 60);
      const endMs = startMs + durationMs;

      if (startMs < earliest) continue;
      if (busy.some(([busyFrom, busyTo]) => startMs < busyTo && endMs > busyFrom)) continue;

      found = { start: new Date(startMs).toISOString(), label: humanLabel(startMs) };
      break;
    }
  }

  if (found) slots.push(found);
}

return [{ json: { ...request, slots, slot_count: slots.length } }];

// Writes the offer email. Sent as HTML on purpose: in plain text, mail clients
// swallow the line break after a long URL and drag the next characters into the
// link, which quietly breaks every option after the first.

// ---------- EDIT THIS BLOCK ----------
const BASE_URL = 'https://YOUR-N8N-HOST';   // no trailing slash
const COMPANY = 'Your Company';
const SENDER = 'Alex';
// -------------------------------------

const data = $input.first().json;

const esc = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const link = (slot) =>
  `${BASE_URL}/webhook/confirm-booking` +
  `?booking_id=${encodeURIComponent(data.booking_id)}` +
  `&amp;start=${encodeURIComponent(slot.start)}`;

const button = (slot) =>
  `<p style="margin:0 0 14px">` +
  `<a href="${link(slot)}" ` +
  `style="display:inline-block;padding:12px 18px;background:#14201f;color:#ffffff;` +
  `text-decoration:none;border-radius:4px;font-size:15px">` +
  `${esc(slot.label)}</a></p>`;

const message =
  `<div style="font-family:system-ui,Arial,sans-serif;font-size:15px;line-height:1.6;color:#14201f">` +
  `<p>Hi ${esc(data.customer_name) || 'there'},</p>` +
  `<p>Here are the next available visits for ${esc(data.job_summary)}. ` +
  `Tap the one that suits you and it is booked, no phone call needed.</p>` +
  data.slots.map(button).join('') +
  `<p>None of these work? Reply to this email and we will find another time.</p>` +
  `<p>${esc(SENDER)}<br>${esc(COMPANY)}</p>` +
  `</div>`;

return [{
  json: {
    ...data,
    subject: `Three times we can come out, ${data.customer_name || 'neighbour'}`,
    message,
  },
}];

// Only the columns the sheet holds.
const src = $('Draft Offer Email').first().json;

return [{
  json: {
    booking_id: src.booking_id,
    created_at: src.created_at,
    customer_name: src.customer_name,
    email: src.email,
    phone: src.phone,
    job_type: src.job_type,
    job_summary: src.job_summary,
    duration_min: src.duration_min,
    status: 'offered',
    booked_start: '',
    booked_end: '',
    event_id: '',
    reminder_sent: '',
  },
}];

