// Reads the click. Nothing is trusted beyond the booking id and the start time.
return $input.all().map((item) => {
  const query = item.json.query || {};
  return {
    json: {
      booking_id: String(query.booking_id || '').trim(),
      chosen_start: String(query.start || '').trim(),
    },
  };
});

// Builds the calendar event from the stored booking and the chosen start time.
const choice = $('Parse Slot Selection').first().json;

// Spreadsheet headers often carry a stray trailing space.
const row = {};
for (const [key, value] of Object.entries($input.first().json)) row[key.trim()] = value;

const start = new Date(choice.chosen_start);
const end = new Date(start.getTime() + Number(row.duration_min || 60) * 60000);

return [{
  json: {
    booking_id: row.booking_id,
    customer_name: row.customer_name,
    email: row.email,
    phone: row.phone,
    job_summary: row.job_summary,
    duration_min: row.duration_min,
    start: start.toISOString(),
    end: end.toISOString(),
    summary: `${row.job_summary || 'Service visit'} - ${row.customer_name || 'customer'}`,
    description:
      `Booking: ${row.booking_id}\n` +
      `Customer: ${row.customer_name}\n` +
      `Phone: ${row.phone}\n` +
      `Email: ${row.email}\n` +
      `Job: ${row.job_summary}`,
  },
}];

// Records the outcome against the original row.
const appointment = $('Build Appointment Details').first().json;
const event = $('Create Calendar Appointment').first().json;

return [{
  json: {
    booking_id: appointment.booking_id,
    status: 'booked',
    booked_start: appointment.start,
    booked_end: appointment.end,
    event_id: event.id || '',
  },
}];

// Runs once a day over the whole sheet. Two jobs: remind people whose visit is
// tomorrow, and hand back offers nobody ever clicked.

// ---------- EDIT THIS BLOCK ----------
const REMIND_FROM_HOURS = 12;    // remind when the visit is between these two
const REMIND_TO_HOURS = 36;      // many hours away
const OFFER_EXPIRY_HOURS = 48;   // an unclicked offer goes back to dispatch
const TIMEZONE = 'America/Chicago';
// -------------------------------------

const HOUR = 60 * 60 * 1000;
const now = Date.now();

const when = (iso) => new Intl.DateTimeFormat('en-US', {
  timeZone: TIMEZONE,
  weekday: 'long', month: 'long', day: 'numeric',
  hour: 'numeric', minute: '2-digit',
}).format(new Date(iso));

const actions = [];

for (const item of $input.all()) {
  // Spreadsheet headers often carry a stray trailing space.
  const row = {};
  for (const [key, value] of Object.entries(item.json)) row[key.trim()] = value;

  const status = String(row.status || '').trim().toLowerCase();

  const common = {
    booking_id: row.booking_id,
    customer_name: row.customer_name,
    email: row.email,
    phone: row.phone,
    job_summary: row.job_summary,
  };

  if (status === 'booked') {
    const alreadyReminded = String(row.reminder_sent || '').trim() !== '';
    if (alreadyReminded || !row.booked_start) continue;

    const hoursAway = (new Date(row.booked_start).getTime() - now) / HOUR;
    if (hoursAway < REMIND_FROM_HOURS || hoursAway > REMIND_TO_HOURS) continue;

    actions.push({
      json: {
        ...common,
        action: 'remind',
        booked_start: row.booked_start,
        visit_label: when(row.booked_start),
      },
    });
    continue;
  }

  if (status === 'offered') {
    if (!row.created_at) continue;

    const ageHours = (now - new Date(row.created_at).getTime()) / HOUR;
    if (ageHours < OFFER_EXPIRY_HOURS) continue;

    actions.push({
      json: {
        ...common,
        action: 'expire',
        age_hours: Math.round(ageHours),
      },
    });
  }
}

return actions;

// Stamps the reminder so it is never sent twice.
const src = $('Determine Daily Actions').item.json;

return {
  json: {
    booking_id: src.booking_id,
    reminder_sent: new Date().toISOString(),
  },
};

